import Component from 'flarum/common/Component';
import classList from 'flarum/common/utils/classList';
import { formatLine, formatOdds, sideLine } from '../../common/odds';
import { marketLabel, selectionLabel } from '../labels';
import { prefs } from '../prefs';
import { slip } from '../state/slip';
/** One price. Tapping it adds the selection to the slip, or takes it off. */
export default class OddsButton extends Component {
  view() {
    const {
      event,
      market,
      selection,
      named
    } = this.attrs;
    const line = sideLine(market.type, selection.key, market.line);
    const open = event.bettable && market.status === 'open' && selection.odds !== null;
    const picked = slip.has(selection.id);
    const label = selectionLabel(event, market.type, selection.key, selection.label, market.line);
    return m("button", {
      type: "button",
      className: classList('Longshot-odds', {
        'is-picked': picked,
        'is-won': selection.result === 'win',
        'is-lost': selection.result === 'lose'
      }),
      disabled: !open,
      "aria-pressed": picked ? 'true' : 'false',
      "aria-label": `${label} ${formatOdds(selection.odds, prefs.odds)}`,
      onclick: () => slip.toggle({
        selection: selection.id,
        odds: selection.odds,
        line: market.type === 'spread' || market.type === 'total' ? market.line : null,
        label,
        market: marketLabel(market.type, market.label),
        marketType: market.type,
        event: {
          id: event.id,
          name: event.name
        }
      })
    }, named ? m("span", {
      className: "Longshot-odds-name"
    }, label) : null, !named && line !== null ? m("span", {
      className: "Longshot-odds-line"
    }, market.type === 'total' ? `${selection.key === 'over' ? 'O' : 'U'} ${Number(line)}` : formatLine(line)) : null, m("span", {
      className: "Longshot-odds-price"
    }, formatOdds(selection.odds, prefs.odds)));
  }
}
flarum.reg.add('ernestdefoe-longshot', 'forum/components/OddsButton', OddsButton);